			function onBtnSearchSearch( /* cpr.events.CUIEvent */ e) {

			    // 그리드 데이터 변경사항 체크
			    if (util.Grid.isModified(app, "grdMainList", "CRM", search)) return false;

			    // 조회조건 유효성 체크
			    if(!util.validate(app, "grpSearch")) return false;

			    var voDmSearchParam = app.lookup("dmSearch");
			    var vbSearchKeyWord = false;

			    voDmSearchParam.getColumnNames().forEach(function(colNm){
			        if(colNm != "strSearchKey"){
			            var vsVal = voDmSearchParam.getValue(colNm);
			            if(!ValueUtil.isNull(vsVal)){
			                vbSearchKeyWord = true;
			                return false;
			            }
			        }               
			    });
			    if(vbSearchKeyWord){
			        app.lookup("subList").addRequestData(voDmSearchParam);
			        vbSearchKeyWord = false;
			    }

			    doList();
			}

