			function onGrdMainListRowCheck(e){                      // 2022-11-18 요건정리 후 적용여부 확인
			    var grdMainList = e.control;
			    
			    var dsList = app.lookup("dsList");
			    
			    var nIdx = util.Grid.getIndex(app, "grdMainList");
			    console.log("nIdx : " + nIdx);
			    
			    var sRsfrInstNo = util.Grid.getCellValue(app, "grdMainList", "RSFR_INST_NO", nIdx); // 제공주체
			    console.log("sRsfrInstNo : " + sRsfrInstNo);
			    var sUnt = util.Grid.getCellValue(app, "grdMainList", "UNT_TASKWK_SE_CD", nIdx); // 단위업무구분코드
			    var PIC_UP_INST_NO = util.Grid.getCellValue(app, "grdMainList", "PIC_UP_INST_NO", nIdx); // 상위
			    var PIC_INST_NO = util.Grid.getCellValue(app, "grdMainList", "PIC_INST_NO", nIdx); // 담당자 기관.
			    /*
			     * 체크박스 선택 여부 수정 쿼리로 승인 할 수 있는 목록만 축출하도록 처리. Taesoo Song 20230418
			     * 시스템총괄관리자 모든 기관 승인.
			     * 이주, 내일 :자신하위(1단계) 기관만 승인 본인등록기관 제외
			     * 나머지 : 등록기관내에서 승인(담당자 소속 기관)
			     */
			    // 시스템 총괄 관리자는 모든 목록 승인 가능.
			    
			    if(groupAuthrtSeCd == "100" || groupAuthrtSeCd == "200") {  //2022.12.05단위업무 판단은 추후 예정
			        grdMainList.setCheckRowIndex(nIdx, true);
			    } else {
			        if((untTaskwk == "U09" || untTaskwk == "U10") && instTypeSeCd == "6" && (PIC_UP_INST_NO == instNo)){
			            //이주/내일(8:시군구수행기관) : 위탁기관에서 등록한 자원제공서비스을 동일 단위업무구분으로 이주/내일(6:재단및기관)의 상위기관에서 승인처리
			            grdMainList.setCheckRowIndex(nIdx, true);
			            
			        //}else if((sRsfrInstNo == instNo) && (groupAuthrtSeCd+'').substr(1, 2) == '10'){
			        // 2023-04-05 총괄관리자 또는 기관관리자 승인 가능하게 변경 Taesoo Song
			        // 20230420 담당자 소속기관 종사자는 다 승인 가능토록 변경. Taesoo Song
			        //}else if((PIC_INST_NO == instNo) && ((groupAuthrtSeCd+'').substr(1, 2) == '10' || (groupAuthrtSeCd+'').substr(1, 2) == '20')){ 
			        }else if((PIC_INST_NO == instNo)){ 
			            //해당기관에서 등록한 자원제공서비스을 동일기관에서 승인처리
			            grdMainList.setCheckRowIndex(nIdx, true);
			        }else{
			            grdMainList.setCheckRowIndex(nIdx, false);
			        }
			    }
			    
			    app.lookup("grpData").redraw();
			}

